const scenarios = {
    TypeScript: [
        ["Easy", "Type a job listing received from the API", "A job card reads title, company, and salary from an API record. Define a TypeScript type for those fields, make salary optional, and update the component so a missing salary renders 'Not listed' instead of throwing.", "Use an interface with required title/company and optional salary; narrow salary before rendering. A record without salary remains valid.", "An empty title is invalid data and should be handled at the API boundary rather than hidden with a fabricated title.", "type Job = { id: string; title: string; company: string; salary?: string };\nfunction Salary({ job }: { job: Job }) { return <span>{job.salary ?? 'Not listed'}</span>; }", "Add a discriminated API state so a failed request cannot be mistaken for an empty listing."],
        ["Easy", "Give a reusable button a safe prop contract", "A Button component is used for navigation and for saving a record. Define props so callers provide a label and an action, the button cannot submit a surrounding form accidentally, and disabled state is optional.", "Declare label, onClick, and optional disabled; fix type to button and pass the event callback through. Both call sites remain explicit about their action.", "A disabled button must not invoke its action, and the label must remain visible to assistive technology.", "type ActionButtonProps = { label: string; onClick: () => void; disabled?: boolean };\nfunction ActionButton({ label, onClick, disabled = false }: ActionButtonProps) { return <button type='button' onClick={onClick} disabled={disabled}>{label}</button>; }", "Extend the type with a loading state while keeping the accessible label stable."],
        ["Easy", "Model request status as a TypeScript union", "A jobs page stores loading, success, and error flags separately, allowing impossible combinations such as loading and error at once. Replace them with a discriminated union and render a message for each state.", "Use a status-tagged union; success alone carries the job array, error carries a safe message, and loading carries no stale result by implication.", "An empty successful array means no matches; it is not the same as a failed request.", "type JobState = { status: 'loading' } | { status: 'error'; message: string } | { status: 'success'; jobs: Job[] };\nfunction render(state: JobState) { switch (state.status) { case 'loading': return 'Loading'; case 'error': return state.message; case 'success': return state.jobs.length ? 'Results' : 'No jobs'; } }", "Add an unauthorized state without weakening the distinction between network failure and an empty result."],
        ["Medium", "Build a generic typed result table", "A reusable table displays jobs and projects. Define a generic column type keyed by the row shape, then implement a renderer that cannot request a property absent from the chosen row type.", "Use Column<T, K extends keyof T> and a generic table parameterized by T; keep the row key separate from display formatting.", "A formatter may return React content, but should not silently coerce unknown server data into trusted fields.", "type Column<T, K extends keyof T = keyof T> = { key: K; heading: string; render?: (row: T) => React.ReactNode };\nfunction cell<T, K extends keyof T>(row: T, column: Column<T, K>) { return column.render ? column.render(row) : String(row[column.key] ?? ''); }", "Add a stable row-key callback and explain why array indexes are unsafe for sortable rows."],
        ["Medium", "Parse unknown JSON before trusting it", "A settings endpoint returns JSON that may be malformed or have a missing theme field. Accept the body as unknown, validate its shape, and return a safe default only when the contract explicitly allows it.", "Treat JSON.parse output as unknown, check object shape and allowed theme values, and produce either a validated Settings value or a typed error.", "A string 'dark;script' must not pass merely because it is truthy.", "type Settings = { theme: 'light' | 'dark' };\nfunction parseSettings(value: unknown): Settings { if (typeof value !== 'object' || value === null || !('theme' in value) || (value.theme !== 'light' && value.theme !== 'dark')) throw new Error('Invalid settings response'); return { theme: value.theme }; }", "Make validation report the field path without logging the entire response."],
        ["Medium", "Use a discriminated union for a save reducer", "A profile editor has idle, saving, saved, and failed states. Define a union and reducer actions so a failed save preserves the draft and success can only include the server-confirmed profile.", "Use status-specific payloads and exhaustive switch handling; dispatch saved only after the request resolves with a valid profile.", "A network timeout must not clear the edited draft or display Saved.", "type SaveState = {status:'idle'; draft:Profile} | {status:'saving'; draft:Profile} | {status:'saved'; profile:Profile} | {status:'failed'; draft:Profile; message:string};\nfunction assertNever(value: never): never { throw new Error(`Unhandled state: ${value}`); }", "Add a retry action that retains the draft and moves failed back to saving."],
        ["Hard", "Type a paginated API client without losing envelope metadata", "A typed job client must accept filters and a positive page, validate the server response envelope, and return records plus page metadata. The current UI must not accidentally assume a single page contains every listing.", "Define request/query and response types, parse the JSON as unknown, validate data and pagination fields, and expose the page metadata to the caller.", "A 200 response with data missing or pagination malformed is a contract error, not an empty successful result.", "type Page<T> = { data: T[]; pagination: { page: number; limit: number; total: number; totalPages: number } };\nasync function getJobs(query: JobQuery): Promise<Page<Job>> { const response = await api.get('/jobs', { params: query }); if (!isJobPage(response.data)) throw new Error('Invalid jobs response'); return response.data; }", "Use a schema validator at the boundary and ensure page changes preserve current filters."],
        ["Hard", "Make API errors exhaustive and non-sensitive", "A frontend API helper receives validation, unauthenticated, forbidden, server, and network failures. Create a discriminated error type and map each case to safe user feedback without exposing stack traces or response internals.", "Represent known HTTP statuses and transport failures explicitly; preserve validation field messages only when they meet the API contract and use a generic message for server faults.", "A server 500 body containing a stack trace is never rendered directly.", "type ApiFailure = {kind:'validation'; fields:Record<string,string>} | {kind:'unauthenticated'} | {kind:'forbidden'} | {kind:'server'} | {kind:'network'};\nfunction messageFor(error: ApiFailure) { switch(error.kind) { case 'validation': return 'Check the highlighted fields.'; case 'unauthenticated': return 'Sign in again.'; case 'forbidden': return 'You do not have access.'; case 'server': return 'The request failed. Try again.'; case 'network': return 'Could not connect. Check your connection.'; } }", "Add exhaustive compile-time checking and tests proving that no raw server body is displayed."],
        ["Hard", "Type a reusable field-path accessor safely", "An API form displays errors for nested paths such as address.city and education.0.degree. Implement a typed-safe path lookup strategy or a constrained schema map, and reject paths not explicitly supported by the form.", "Map server field identifiers to known controls instead of evaluating arbitrary property paths; handle absent fields with a summary error.", "A malicious path such as __proto__.polluted must never mutate or traverse object prototypes.", "const fields = { title: 'title', city: 'address.city', degree: 'education.0.degree' } as const;\ntype FieldName = keyof typeof fields; function fieldPath(name: FieldName) { return fields[name]; }", "Add tests for unknown field IDs and prototype-related path strings."],
    ],
    "State Management": [
        ["Easy", "Derive a saved-jobs count from one source", "A saved-jobs screen stores both the saved ID list and a separate count, which drifts after removing a job. Keep one source of truth and derive the visible count and saved state for each row.", "Store the IDs once, derive Set membership and count, and remove by ID with a functional state update.", "Removing the same ID twice should leave the list and count unchanged.", "const [savedIds, setSavedIds] = useState<string[]>([]);\nconst saved = new Set(savedIds); const count = saved.size;\nconst remove = (id: string) => setSavedIds(current => current.filter(item => item !== id));", "Add a test that toggles two records and verifies the derived count after each action."],
        ["Easy", "Lift a shared location filter to its owner", "A filter toolbar and results list both need the selected location. They currently keep separate local values and show contradictory UI. Move the state to their nearest common parent and pass controlled props.", "The parent owns the filter value; toolbar receives value/onChange and results receives the same value. Do not introduce global state for one local subtree.", "Clearing the filter updates both the control and the visible result set.", "function JobsPage() { const [location, setLocation] = useState(''); return <><Filters location={location} onLocationChange={setLocation}/><Results location={location}/></>; }", "Add a second filter and explain which component should own their combined query state."],
        ["Easy", "Keep an expanded panel local", "Only one exercise card needs to remember whether its explanation is expanded. Avoid adding this temporary view state to an application-wide store; implement the smallest state owner.", "Use local component state for expansion, with a button that controls the section and exposes aria-expanded.", "Changing the selected phase should not accidentally persist a hidden expansion state as learner completion.", "function ExerciseDetails() { const [open, setOpen] = useState(false); return <><button aria-expanded={open} onClick={() => setOpen(value => !value)}>Details</button>{open && <section>Explanation</section>}</>; }", "If multiple cards must be mutually exclusive, move only the selected exercise ID to their list parent."],
        ["Medium", "Normalize a project collection for reliable updates", "A project list contains duplicate copies of records in list, selected detail, and saved state. Design a reducer with an entity map and ordered IDs so one confirmed update is reflected everywhere.", "Store entities by stable ID and keep ordering separately; update one entity immutably and derive selected detail by ID.", "A response for project p2 must not overwrite p1 when the user changes selection during the request.", "type State = { ids: string[]; byId: Record<string, Project> };\nfunction updateProject(state: State, project: Project): State { return { ...state, byId: { ...state.byId, [project.id]: project } }; }", "Add stale-request protection keyed to the selected project ID."],
        ["Medium", "Use a reducer for coupled filters and pagination", "Changing a role filter while on page 6 should reset the page to 1, while changing page should retain role, location, and type. Model the transitions so callers cannot forget the reset rule.", "Use a reducer action for filter changes that updates the filter and resets page atomically; page actions preserve the filters.", "Submitting the same filter does not create an invalid page 0 or clear unrelated filters.", "type SearchState = { role:string; location:string; page:number };\ntype Action = {type:'filter'; role?:string; location?:string} | {type:'page'; page:number};\nfunction reducer(s:SearchState,a:Action):SearchState { return a.type==='page' ? {...s,page:a.page} : {...s,...a,page:1}; }", "Add a maximum page-size invariant and keep server validation authoritative."],
        ["Medium", "Separate server cache from editable form state", "A profile query cache is overwritten on every keystroke, causing the page header and saved data to look like they already changed. Keep an editable draft separate from the last server-confirmed profile.", "Initialize a draft from confirmed data, update only the draft while typing, and replace confirmed state only after a successful save response.", "If saving fails, keep the draft and leave the confirmed profile unchanged.", "type ProfileState = { confirmed:Profile; draft:Profile; status:'idle'|'saving'|'error' };\nfunction edit(state:ProfileState, patch:Partial<Profile>):ProfileState { return {...state,draft:{...state.draft,...patch}}; }", "Define how a refreshed server profile is reconciled when the user has unsaved edits."],
        ["Hard", "Rollback an optimistic save without clobbering newer edits", "A user toggles a saved job optimistically, then toggles it again before the first request fails. Design request sequencing so a late failure does not restore stale state over the newer intent.", "Track mutation sequence or serialize toggles per ID; reconcile with authoritative server state and only roll back if the failed operation is still the latest pending intent.", "Out-of-order responses for the same job cannot leave the UI opposite to the last user action.", "const latest = useRef(new Map<string, number>());\nasync function toggle(id:string,next:boolean) { const seq=(latest.current.get(id)??0)+1; latest.current.set(id,seq); setSaved(id,next); try { await api.setSaved(id,next); } catch { if (latest.current.get(id)===seq) await refetchSaved(); } }", "Extend the strategy for two different job IDs whose requests can safely run concurrently."],
        ["Hard", "Design selectors for normalized roadmap state", "A roadmap store has topic records, completed topic IDs, and selected phase. Compute phase completion and the next incomplete topic without duplicating derived totals in mutable state.", "Build selectors from normalized records and completion IDs; memoize only if measurement shows repeated calculation is costly.", "An unknown topic ID is ignored or surfaced as invalid input; it is not counted as completed work.", "type RoadmapState = { topics:Record<string,Topic>; phaseIds:string[]; completed:Set<string> };\nfunction phaseProgress(s:RoadmapState, ids:string[]) { const valid=ids.filter(id=>s.topics[id]); const done=valid.filter(id=>s.completed.has(id)); return {total:valid.length,done:done.length,next:valid.find(id=>!s.completed.has(id))}; }", "Add account switching and ensure the previous user's completion set is replaced, not merged."],
        ["Hard", "Reconcile offline edits with a server snapshot", "A roadmap editor queues topic-completion changes while offline. On reconnect, a fresh server snapshot arrives after local edits. Define a versioned action log and merge policy that avoids silently discarding either confirmed server state or newer local intent.", "Keep server snapshot and pending local actions distinct, replay only valid idempotent actions, and surface conflicts that cannot be safely merged.", "A duplicate completion action should be idempotent, while a deleted topic must not be recreated from stale local state.", "type PendingAction = {id:string; topicId:string; value:boolean; baseVersion:number};\nfunction replay(snapshot:Snapshot, actions:PendingAction[]) { return actions.reduce((state,action)=>applyIfValid(state,action),snapshot); }", "Specify retry, conflict resolution, and user-visible pending status without claiming a save before confirmation."],
    ],
    Performance: [
        ["Easy", "Read a real frontend performance trace", "A route feels slow, but no measurement exists. Use browser Performance and Network tools to separate asset download, JavaScript execution, rendering, and server waiting before choosing one improvement.", "Record a reproducible load and identify the largest measured phase; propose a change tied to that evidence and compare the same metric afterward.", "A long task in scripting is not fixed by changing the database query without evidence that the server is slow.", "performance.mark('route-start');\nrequestAnimationFrame(() => performance.mark('first-frame')); performance.measure('route-to-frame','route-start','first-frame');", "Write a before/after measurement plan with device, cache, route, and metric held constant."],
        ["Easy", "Prevent layout shift in a job-card image", "Company logos have unknown dimensions, so cards jump when each image loads. Set an aspect ratio or width/height, provide an appropriate fit rule, and explain how to verify reduced layout shift.", "Reserve the image box before the request resolves and keep the crop consistent; measure layout shift on the same page load.", "A broken image should retain its reserved space and show an honest fallback.", "<img src={logoUrl} alt={`${company} logo`} width={40} height={40} style={{objectFit:'contain'}} />", "Test slow network and missing-image cases, not just a warm cache."],
        ["Easy", "Defer a non-critical below-the-fold image", "A long portfolio page downloads every large project image before the first viewport is useful. Choose safe lazy loading for off-screen images and keep the first meaningful image prioritized when appropriate.", "Use loading=lazy for below-the-fold content and preserve intrinsic dimensions; do not lazy-load the likely LCP image by default.", "An image required immediately above the fold should not wait for intersection if it is the main content.", "<img src={project.image} alt={project.alt} width={640} height={400} loading='lazy' decoding='async' />", "Compare the initial network waterfall and ensure important content still appears promptly."],
        ["Medium", "Fix an expensive filtered list using evidence", "A measured React profile shows every job row rerenders when the search field changes, even when its job and saved status did not. Identify a narrow memoization boundary and the stable props it requires.", "Profile first; memoize an individual row only if stable job and callbacks make it skippable, and keep filtering correct as the query changes.", "Memoizing the entire page while passing a new object prop each render does not solve the row work.", "const JobRow = memo(function JobRow({ job, saved, onToggle }: Props) { return <article>{job.title}<button onClick={() => onToggle(job.id)}>{saved ? 'Saved' : 'Save'}</button></article>; });\nconst onToggle = useCallback((id:string)=>setSaved(s=>toggleId(s,id)),[]);", "Re-profile with realistic list size and confirm the interaction remains responsive."],
        ["Medium", "Debounce search without showing stale results", "A title search sends a request for every keystroke. Add a short debounce, cancel or ignore obsolete requests, and keep the current results labeled while the new query loads.", "Debounce input, abort the prior request or use a sequence token, and commit only the response matching the latest query.", "A slow response for 're' must not replace the newer result for 'react'.", "useEffect(() => { const controller=new AbortController(); const timer=setTimeout(()=>load(query,{signal:controller.signal}),250); return()=>{clearTimeout(timer);controller.abort();}; },[query]);", "Add retry behavior that repeats the current query rather than the last completed one."],
        ["Medium", "Reduce a heavy route's initial JavaScript", "A production report shows a charting library is loaded before the user visits the analytics route. Split that route so its chart code is requested when needed, with a useful loading state.", "Use route-level dynamic import and a suspense/loading fallback; confirm the route chunk is separate in the production build output.", "The fallback must not leave keyboard users with a blank region and no status.", "const Analytics = lazy(() => import('./pages/Analytics.jsx'));\n<Suspense fallback={<p role='status'>Loading analytics…</p>}><Analytics /></Suspense>", "Compare initial and analytics-route chunk sizes and check navigation after the split."],
        ["Hard", "Virtualize a large accessible results list", "A search result contains 8,000 records and profiling confirms DOM layout is the bottleneck. Propose a virtualized list with stable keys, keyboard behavior, and a non-virtualized small-list path if useful.", "Render only the viewport plus overscan, preserve stable record identity and focus behavior, and ensure the scroll container has a clear accessible name and usable total-result context.", "A focused row cannot disappear from the DOM while keyboard interaction depends on it.", "const rowVirtualizer = useVirtualizer({ count: jobs.length, getScrollElement: () => parentRef.current, estimateSize: () => 72, overscan: 6, getItemKey: index => jobs[index].id });", "Test rapid filtering, screen-reader context, keyboard focus, and a result count that reflects all matches."],
        ["Hard", "Set and enforce a route performance budget", "A frontend release repeatedly grows its entry bundle and delays the first useful view on mid-range mobile. Define a measurable budget, collect build/lab evidence, and create an actionable failure gate.", "Choose metrics tied to user experience, capture baseline on controlled hardware/network, set thresholds with a warning then blocking period, and assign ownership for regressions.", "A passing desktop score does not prove a mobile budget is met.", "// Example CI gate: fail when compressed entry JS exceeds the agreed budget.\nif (entryGzipBytes > budgetBytes) throw new Error('Entry bundle budget exceeded');", "Include field monitoring after release and a rollback threshold for real-user regressions."],
        ["Hard", "Find a long task without hiding the interaction cost", "A filter interaction takes 900 ms on a mid-range device. Instrument input-to-next-paint and inspect a browser trace to distinguish synchronous filtering, React rendering, and layout. Propose one targeted mitigation and a remeasurement plan.", "Measure the same interaction on representative data, attribute time to a specific task, then choose indexing, deferred rendering, virtualization, or algorithm changes only when the trace supports it.", "Moving work to a timeout may improve input responsiveness while leaving total completion time unchanged; report both metrics.", "performance.mark('filter-input');\nrequestAnimationFrame(()=>requestAnimationFrame(()=>performance.measure('input-to-paint','filter-input')));\n// Record the trace and compare the same query and dataset before and after.", "Test keyboard input, result accuracy, and response time across the supported dataset sizes."],
    ],
    Testing: [
        ["Easy", "Test a required profile field by its accessible label", "A profile form requires a display name. Write a component test that finds the control by its visible label, submits whitespace, and verifies an inline error without querying implementation-specific class names.", "Use role/label queries, simulate submit, assert the accessible error and invalid relationship, and confirm no success state appears.", "A non-empty whitespace string remains invalid after trimming.", "render(<ProfileForm onSave={save}/>)\nawait user.click(screen.getByRole('button',{name:/save profile/i}));\nexpect(screen.getByRole('textbox',{name:/display name/i})).toHaveAttribute('aria-invalid','true');", "Add a valid-name test asserting onSave receives the trimmed value exactly once."],
        ["Easy", "Unit-test a derived completion selector", "A roadmap completion selector receives four topic IDs and a completion set. Test zero completed, two completed, and an unknown ID to ensure percentages and counts use only valid topics.", "Test exact counts and percentage boundaries, and define the empty denominator as a neutral 0% without naming a strongest/weakest topic.", "Duplicate completion IDs cannot inflate the completed count.", "expect(selectProgress(['a','b'],new Set())).toEqual({done:0,total:2,percent:0});\nexpect(selectProgress(['a','b'],new Set(['a','a','unknown']))).toEqual({done:1,total:2,percent:50});", "Add a property-style case ensuring percent remains between 0 and 100."],
        ["Easy", "Verify an empty API response is an empty state", "A jobs component receives a successful response with data: []. Test that it shows the no-results state, retains the search controls, and does not show an API error or fabricated listing.", "Resolve the authenticated service with an empty array, assert the empty message and reset action, and assert no result card exists.", "A rejected promise must render an error state distinct from the successful empty state.", "api.getJobs.mockResolvedValue({data:[]});\nrender(<JobsPage/>); await screen.findByText(/no jobs match/i);\nexpect(screen.queryByRole('alert')).toBeNull();", "Add the complementary rejected-request case and a retry assertion."],
        ["Medium", "Test a loading-to-error API transition", "A profile request rejects after the loading UI appears. Verify loading is announced, then replaced with a safe retryable error while stale default profile values are not shown as real data.", "Use a deferred promise to inspect loading, reject it, assert the error alert and retry button, and ensure no false success content remains.", "Retry resolving successfully should replace the error state with the actual profile.", "const pending = deferred<Profile>(); api.getProfile.mockReturnValue(pending.promise);\nrender(<ProfilePage/>); expect(screen.getByRole('status')).toHaveTextContent(/loading/i);\npending.reject(new Error('network')); await screen.findByRole('alert');", "Use the retry button in the test and resolve a second deferred request."],
        ["Medium", "Test a dialog using keyboard interaction", "A details dialog opens from a result card. Verify focus enters the dialog, Escape closes it, focus returns to the opener, and background controls cannot be activated while modal content is open.", "Drive the real keyboard sequence and assert dialog semantics plus focus restoration; do not test only a boolean state variable.", "Closing via the close button and Escape both restore focus to the same opener.", "await user.click(screen.getByRole('button',{name:/view details/i}));\nconst dialog=screen.getByRole('dialog'); expect(dialog).toBeVisible();\nawait user.keyboard('{Escape}'); expect(screen.getByRole('button',{name:/view details/i})).toHaveFocus();", "Check that a long dialog remains scrollable without hiding its primary action."],
        ["Medium", "Mock an authenticated API boundary without mocking UI behavior", "A saved-jobs view calls an authenticated service and handles 401 separately from 500. Mock the service module at the boundary and assert the UI message and retry/session action for each status.", "Keep component rendering and user actions real, isolate only the network service, and assert that raw response bodies are not exposed.", "A network rejection without an HTTP status must not be mislabeled as expired authentication.", "api.listSaved.mockRejectedValueOnce({status:401});\nrender(<SavedJobs/>); await screen.findByText(/sign in again/i);\nexpect(screen.queryByText(/stack trace/i)).toBeNull();", "Add 403 and generic server cases while verifying the request is not retried in a loop."],
        ["Hard", "Prevent a stale request race in a search test", "Two search requests resolve out of order: 're' starts first and 'react' starts second. Build a deterministic test proving only the latest query populates results and the loading state resolves correctly.", "Control both promises, resolve the newer request first and older one last, and assert that stale data cannot replace the current result.", "Unmount during a pending request should not update the component or produce an unhandled rejection.", "const first=deferred<Result[]>(), second=deferred<Result[]>(); api.search.mockReturnValueOnce(first.promise).mockReturnValueOnce(second.promise);\nawait user.type(input,'re'); await user.type(input,'act'); second.resolve([{title:'React role'}]); first.resolve([{title:'Remote role'}]);\nexpect(await screen.findByText('React role')).toBeVisible(); expect(screen.queryByText('Remote role')).toBeNull();", "Repeat with AbortController and assert that intentional aborts are not shown as user-facing errors."],
        ["Hard", "Design integration coverage for authenticated profile editing", "A profile editor loads authenticated data, preserves multiple education entries, submits one edit, and handles validation failure. Specify an integration test using a test API boundary and prove another account's data is never substituted.", "Test the route with a known authenticated identity, verify response ownership and unchanged entries, then simulate 400 and 401 responses without accessing production data.", "A missing optional field must not silently erase untouched education or experience records.", "await page.route('**/api/profile', route => route.fulfill({json:{userId:'u-test',education:[first,second]}}));\nawait page.getByLabel('Degree').fill('Updated degree'); await page.getByRole('button',{name:/save/i}).click();\nexpect(savedPayload.education).toHaveLength(2);", "Add a second identity fixture and assert the API service never requests another user's identifier."],
        ["Hard", "Test partial hydration and account-switch races", "A profile page first renders a cached snapshot, then switches authenticated accounts while an older request is still pending. Design deterministic tests proving the new account wins, no mixed records render, and the older response is ignored.", "Use deferred requests keyed by identity, switch accounts, resolve responses out of order, and assert only the current account's data and completion state remain visible.", "An API failure for the new identity must not fall back to cached private data from the previous identity.", "const oldRequest=deferred<Profile>(), newRequest=deferred<Profile>(); api.getProfile.mockReturnValueOnce(oldRequest.promise).mockReturnValueOnce(newRequest.promise);\nrerender(<ProfilePage userId='user-b'/>); newRequest.resolve(profileB); oldRequest.resolve(profileA); expect(screen.getByText(profileB.name)).toBeVisible();", "Run the race test repeatedly and verify cleanup prevents post-unmount state updates."],
    ],
    Accessibility: [
        ["Easy", "Label a filter and preserve native keyboard use", "A target-role filter is visually titled but has no programmatic label. Add an associated label and ensure a keyboard user can focus it, open options, choose a role, and see the selected value.", "Connect label and control, retain native select semantics, and ensure focus styling is visible in both themes.", "A placeholder option is not a substitute for a persistent label.", "<label htmlFor='role-filter'>Target role</label>\n<select id='role-filter' value={role} onChange={event=>setRole(event.target.value)}><option value=''>Any role</option></select>", "Test keyboard selection and confirm the visible label remains present after a value is chosen."],
        ["Easy", "Choose useful alternative text for a project image", "A portfolio card includes a screenshot that demonstrates a dashboard's layout. Write concise alt text for that informative image and identify when an image should instead use empty alt text.", "Describe the information or function conveyed, not the filename; use empty alt only when the image is decorative or fully redundant.", "Do not repeat the adjacent title verbatim if it adds no information.", "<img src='/media/analytics.png' alt='Analytics dashboard showing monthly signups and a rising trend' />\n<img src='/media/divider.svg' alt='' />", "Provide an adjacent data table when exact chart values are important."],
        ["Easy", "Make icon-only save actions understandable", "A job card uses a bookmark icon with no text. Give it an accessible name that changes between save and remove, and expose its pressed state without hiding the visible icon from sighted users.", "Use a button with a dynamic aria-label and aria-pressed; decorative icon markup is hidden from the accessibility tree.", "Two cards with the same icon still need job-specific accessible names.", "<button type='button' aria-label={saved ? `Remove ${job.title} from saved jobs` : `Save ${job.title}`} aria-pressed={saved}><BookmarkIcon aria-hidden='true'/></button>", "Add a screen-reader test verifying that the action name includes the listing title."],
        ["Medium", "Manage focus for a filter drawer", "On tablet, opening filters overlays the results. Implement dialog semantics, move focus into the drawer, keep focus contained while open, and return it to the Filters button after close.", "Use a labelled dialog, initial focus, focus containment, Escape handling, and restoration. Prevent background interaction while the modal drawer is open.", "A drawer hidden visually but still tabbable is not closed accessibly.", "<div role='dialog' aria-modal='true' aria-labelledby='filters-title'><h2 id='filters-title'>Filters</h2><button type='button'>Close filters</button></div>", "Test open, tab through last control, tab again, Escape, and focus restoration."],
        ["Medium", "Make a results update announcement useful", "A search updates the result count without moving focus. Add a concise polite announcement that reports the new count while avoiding an announcement for every keystroke during rapid input.", "Use a live region with debounced settled results; keep the count visible and do not steal focus from the search field.", "An error response should announce failure rather than announce zero matches.", "<p aria-live='polite' aria-atomic='true'>{status==='success' ? `${total} jobs found` : status==='error' ? 'Search failed; retry available' : ''}</p>", "Check that loading, empty success, and error messages are distinct to assistive technology."],
        ["Medium", "Provide keyboard operation for a custom listbox", "A custom role selector uses clickable divs and cannot be operated without a mouse. Specify the minimum roving-focus and arrow-key behavior, or replace it with a native select if the custom pattern adds no product value.", "Prefer native select for ordinary form selection; if a listbox is necessary, implement roles, selected state, arrow navigation, Home/End, and typeahead consistently.", "Tab should move into and out of the composite once, not stop at every option.", "<select aria-label='Target role' value={role} onChange={e=>setRole(e.target.value)}><option>Any Role</option><option>Frontend Developer</option></select>", "Compare the native control on supported mobile and desktop browsers before maintaining a custom widget."],
        ["Hard", "Audit a dynamic form error summary", "A long application form returns several field errors after submit. Build an accessible error summary that receives focus, links to each invalid field, and remains correct after an individual field is repaired.", "Render a heading and list of links to invalid fields, focus the summary after failed submission, associate each inline message, and remove resolved errors after validation.", "Do not focus the first field if the summary is the chosen entry point; avoid two competing focus moves.", "const summaryRef=useRef<HTMLDivElement>(null);\nif(errors.length) summaryRef.current?.focus();\n<div ref={summaryRef} tabIndex={-1} role='alert' aria-labelledby='errors-title'><h2 id='errors-title'>Fix these fields</h2>{errors.map(e=><a key={e.id} href={`#${e.id}`}>{e.label}: {e.message}</a>)}</div>", "Test keyboard activation of an error link and verify focus lands on its labelled control."],
        ["Hard", "Verify accessible name and status in a modal workflow", "A project delete confirmation contains a title, warning, cancel action, and destructive action. Define a semantic dialog that announces its purpose, has a safe initial focus target, and returns focus after either outcome.", "Use dialog labelled by its heading and described by the warning; initially focus Cancel or another safe control, then restore focus to the delete trigger on close.", "The dialog must not claim deletion succeeded before the server confirms it.", "<dialog aria-labelledby='delete-title' aria-describedby='delete-warning'><h2 id='delete-title'>Delete project?</h2><p id='delete-warning'>This cannot be undone.</p><button autofocus>Cancel</button><button>Delete project</button></dialog>", "Test confirmation success, API failure, Escape behavior, and focus restoration."],
        ["Hard", "Audit a data table with sorting and selection", "A project table supports sortable columns, row selection, and pagination. Specify semantic table markup and keyboard-accessible sort controls, announce sort direction, and preserve selected row identity as page ordering changes.", "Use table headers with buttons for sorting, aria-sort on the active header, stable row IDs, and a selection control whose accessible name identifies the project.", "Sorting must not silently move keyboard focus to a different project row.", "<th scope='col' aria-sort={sort==='title' ? direction : 'none'}><button type='button' onClick={toggleTitleSort}>Project title</button></th>\n<tr key={project.id}><th scope='row'>{project.title}</th></tr>", "Test keyboard sorting, announced direction, selection after sort, and pagination state."],
    ],
    SEO: [
        ["Easy", "Set unique metadata for a public portfolio", "A public portfolio route uses the same generic browser title and description as every other page. Write route-specific title and description based on visible content and avoid promising qualifications the owner has not provided.", "Use a concise unique title and accurate description derived from the real profile and project content.", "A private authenticated dashboard should not be indexed just because public portfolio metadata exists.", "useEffect(()=>{document.title=`${profile.name} — Frontend Portfolio`; setMetaDescription(profile.summary);},[profile.name,profile.summary]);", "Test that two public portfolio routes produce distinct titles and that private routes have the intended indexing policy."],
        ["Easy", "Use semantic headings for a project page", "A project details page uses bold paragraphs styled as headings, making its content outline unusable. Restructure the visible title, overview, and implementation sections with semantic heading levels that match the page hierarchy.", "Use one clear page h1, followed by h2 sections and h3 only for subsections; CSS visual size does not determine semantic level.", "Repeated project cards on a list page should not each create a competing page-level h1.", "<main><article><h1>{project.title}</h1><h2>Overview</h2><p>{project.description}</p><h2>Implementation</h2><p>{project.implementation}</p></article></main>", "Inspect the heading outline and confirm that labels correspond to content actually shown."],
        ["Easy", "Keep a canonical URL aligned with a public route", "A public portfolio can be reached through both a preferred path and a legacy alias. Choose one canonical URL and make sure the canonical points to the real preferred route rather than an invented origin.", "Use the configured public origin and canonical path; redirect aliases where appropriate and keep internal links consistent.", "Do not expose private query data or session tokens in canonical metadata.", "<link rel='canonical' href={`${publicOrigin}/portfolio/${encodeURIComponent(slug)}`} />", "Verify canonical output on the deployed hostname and after a route alias redirect."],
        ["Medium", "Choose prerendering for content that search engines need", "A public portfolio route renders its main content only after a client API call. Evaluate whether static generation, prerendering, or server rendering is needed; state what evidence and hosting capability decide the choice.", "Measure actual crawler-visible HTML and route discovery; use a rendering strategy supported by hosting and keep authenticated user data out of public output.", "Do not claim client-only rendering is always unindexable; test the target crawler/rendering behavior.", "// Build public portfolio HTML from publishable profile data at build/request time.\n// Keep private dashboard routes behind authentication and out of generated pages.", "Compare initial HTML, crawler rendering, freshness requirements, and operational costs before selecting a strategy."],
        ["Medium", "Add structured data only for facts actually displayed", "A public profile author considers adding Person and Project structured data. Map only visible, verified fields, validate the output, and explain how missing employer or credential facts should be treated.", "Use schema fields that match the rendered page and the user's actual public data; omit unknown values and validate the generated JSON-LD.", "Never fabricate ratings, employer verification, job availability, or credentials to gain search visibility.", "const person = { '@context':'https://schema.org', '@type':'Person', name: profile.publicName, url: publicUrl };\n// Add sameAs only for verified public profile URLs.", "Test structured data after publication and remove a field when the visible source data is withdrawn."],
        ["Medium", "Control indexing for authenticated career pages", "Roadmap, resume, and profile pages contain user-specific information. Define robots and response behavior so private routes are authenticated and not added to a public sitemap; explain why robots.txt is not access control.", "Enforce auth on the server, avoid publishing private URLs in the sitemap, and use noindex where appropriate as a secondary indexing signal.", "A crawler can ignore robots rules, so protected content must not rely on them for privacy.", "// Private pages: authentication required; no public sitemap entries.\n// Optional response metadata: X-Robots-Tag: noindex, nofollow", "Review source HTML and sitemap output while unauthenticated and authenticated."],
        ["Hard", "Design an honest sitemap and robots policy", "A site has public landing pages and portfolio profiles plus authenticated job saves and documents. Create a sitemap/robots plan that helps discovery without listing private or duplicate URLs.", "Include only canonical, indexable public routes; exclude private routes from sitemap and protect them at the API/page layer; keep robots directives consistent with redirects and canonical tags.", "Disallowing a URL does not prevent a known URL from appearing in search results or protect its response.", "const sitemapPaths = publicRoutes.filter(route => route.indexable && route.canonical).map(route => route.canonical);\nconst robots = 'User-agent: *\\nAllow: /\\nDisallow: /app/';", "Add a release check that compares sitemap entries against the public-route allowlist."],
        ["Hard", "Prevent duplicate content across portfolio previews", "A profile appears at /u/:name and /portfolio/:slug with identical public content. Define canonical, redirect, and metadata behavior that preserves stable links without creating duplicate indexable copies.", "Choose one canonical public path, redirect the legacy alias when safe, and ensure canonical tags and internal links point to the selected URL.", "If the two pages differ materially, do not canonicalize them blindly; review the content and purpose first.", "app.get('/u/:name', (req,res) => res.redirect(308, `/portfolio/${encodeURIComponent(slugFor(req.params.name))}`));\n// Canonical metadata is rendered from the same public route configuration.", "Verify redirects, canonical tags, and sitemap entries together in a crawl of the deployed site."],
        ["Hard", "Protect private documents from indexing and leakage", "A documents route has user-owned files and extracted text. Design the SEO and routing policy so search engines cannot index document content and unauthenticated responses do not reveal filenames or snippets.", "Require authentication and owner authorization at the data endpoint, exclude the route from public navigation and sitemap, and use noindex only as a secondary safeguard.", "Robots directives do not protect a URL or file from direct access; authorization must deny the request.", "app.get('/app/documents/:id', requireAuth, loadOwnedDocument, (req,res) => res.set('X-Robots-Tag','noindex, nofollow').render('documents'));\n// The file endpoint separately checks req.user.id against document ownership.", "Add anonymous and cross-account tests for the page and file endpoint, plus a sitemap allowlist check."],
    ],
    Deployment: [
        ["Easy", "Build a static frontend with the correct environment", "A Vite application works locally but its deployed build calls localhost. Identify which public API base setting belongs at build time, validate it, and explain why secret credentials must never be embedded in browser variables.", "Use the project's documented public API URL variable, validate the deployment value, and keep provider/database secrets server-side.", "A successful build with an empty API base can still produce a broken deployed integration.", "const apiBase = import.meta.env.VITE_API_BASE_URL;\nif (!apiBase || !/^https:\\/\\//.test(apiBase)) throw new Error('Configure the public HTTPS API URL');", "Test a production build against staging and inspect emitted assets for accidental secrets."],
        ["Easy", "Configure SPA route fallback safely", "A deployed React app loads at / but refreshing /roadmap/react returns a host-level 404. Configure the static host to serve index.html for application routes while preserving real asset and API 404 responses.", "Add a host-specific fallback for frontend navigation paths, keep /api requests on the backend, and verify direct route load and refresh.", "A blanket rewrite that serves index.html for missing JavaScript bundles hides deployment errors.", "// Hosting rule concept: route requests to the SPA shell only after static-file lookup;\n// leave /api/* and missing asset paths to their actual handlers.", "Test nested refresh, a genuinely missing .js asset, and an API 404 separately."],
        ["Easy", "Use an immutable build artifact", "A team deploys source files directly to production and cannot reproduce the exact release that caused an error. Define a build artifact and version identifier that ties deployed assets to a commit.", "Build once in CI, label the artifact with a commit SHA, promote the same artifact, and retain a previous known-good artifact for rollback.", "Rebuilding separately in staging and production can produce different assets from the same nominal source revision.", "const release = { commit: process.env.GIT_SHA, artifact: 'dist', builtAt: new Date().toISOString() };\nif (!release.commit) throw new Error('Missing release commit identifier');", "Add an endpoint or release note that reports a non-sensitive build identifier."],
        ["Medium", "Separate staging and production API configuration", "A deployment pipeline accidentally points the production frontend at staging data. Define environment-specific configuration validation and a release gate that proves the built frontend uses the intended API origin.", "Use explicit staging/production values, fail the pipeline for a mismatched origin, and verify the final generated configuration without printing secrets.", "A localhost fallback must not silently become a production default.", "const expected = process.env.DEPLOY_ENV === 'production' ? 'https://api.example.com' : 'https://staging-api.example.com';\nif (new URL(apiBase).origin !== expected) throw new Error('API origin does not match deployment environment');", "Add a deployment smoke request that checks a non-sensitive health endpoint on the expected origin."],
        ["Medium", "Add CI checks before publishing the frontend", "A frontend release should not publish when focused tests or production build fail. Design a CI sequence that installs the lockfile-defined dependencies, runs coverage tests, builds once, and publishes only the resulting artifact.", "Use deterministic dependency installation, run tests and build as required gates, upload the artifact only after both succeed, and preserve logs without environment secrets.", "A skipped test step due to a missing script should fail clearly rather than look green.", "steps: [ { run: 'npm ci' }, { run: 'npm test -- --run' }, { run: 'npm run build' }, { run: 'upload-artifact: dist' } ]", "Add a separate protected deploy approval after artifact verification."],
        ["Medium", "Configure cache headers for hashed assets", "A release changes application code but some users keep an old JavaScript bundle while receiving a new index.html. Choose cache behavior for the HTML shell and content-hashed assets so deployments remain coherent.", "Use short/no-cache revalidation for index.html and long immutable caching for fingerprinted assets; retain old assets long enough for cached shells to finish loading.", "Do not mark unhashed filenames immutable when their content can change.", "Cache-Control: index.html -> no-cache\nCache-Control: /assets/*-[hash].js -> public, max-age=31536000, immutable", "Test a deployment transition with a cached prior index and confirm referenced chunks remain available."],
        ["Hard", "Plan a safe frontend rollout and rollback", "A new frontend release changes routing and API response handling. Define staged rollout checks, measurable rollback triggers, and a way to restore the prior artifact without rebuilding or changing user data.", "Promote an immutable artifact, smoke-test critical authenticated and public flows, monitor error and API failure rates, and restore the prior artifact if agreed thresholds are exceeded.", "A visual success on the landing page does not prove protected routes or upload flows are healthy.", "if (errorRate > rollbackThreshold || criticalSmokeFailed) { deploy(previousArtifact); recordIncident(); }\n// Keep data migrations and irreversible changes out of a static-asset rollback.", "Specify who owns the decision and how the team confirms the previous release is stable."],
        ["Hard", "Protect source maps and runtime configuration", "A production build needs useful error diagnosis, but public source maps may reveal source structure and runtime config might accidentally include secrets. Design a controlled source-map upload and configuration review.", "Upload maps to restricted error monitoring, disable public map serving if not intended, and scan the emitted browser bundle for secret-like server configuration.", "Obfuscation is not a substitute for keeping secrets out of client code.", "// CI: upload dist/**/*.map to restricted monitoring, then remove maps from public artifact.\n// Scan public assets for known secret variable names and block on matches.", "Verify access controls for uploaded maps and document retention and incident access."],
        ["Hard", "Deploy with immutable assets and a recoverable release", "A production release changes routes and client/API compatibility. Define a staged release process that validates the artifact, handles cached HTML and hashed assets, and rolls back without exposing user data or rebuilding a different artifact.", "Promote one immutable build, smoke-test public and authenticated flows, monitor errors against agreed thresholds, and restore the prior artifact while keeping old hashed chunks available through the cache window.", "Rolling back frontend assets cannot reverse a destructive database migration; keep those operations independently compatible.", "const release = { sha: process.env.GIT_SHA, artifact: 'dist' };\nif (!release.sha || !criticalSmokePassed) throw new Error('Release gate failed');\nif (errorRate > rollbackThreshold) deploy(previousArtifact);", "Include a rollback drill and document who decides when thresholds require restoration."],
    ]
};

const slug = (value) => value.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");

const buildExercise = (topic, [difficulty, title, problem, answer, edge, solution, followUp], index) => {
    const id = `frontend-advanced-${slug(topic)}-${difficulty.toLowerCase()}-${index + 1}-v1`;
    return {
        id, career: "Frontend Developer", phase: "Advanced Frontend", topic, title, difficulty,
        estimatedTime: difficulty === "Easy" ? "20–30 minutes" : difficulty === "Medium" ? "35–50 minutes" : "50–70 minutes",
        kind: "coding", language: topic === "SEO" || topic === "Deployment" ? "Frontend engineering" : "React / TypeScript",
        problemStatement: `${problem} State the acceptance criteria and explain how your result will be verified in a realistic user workflow.`,
        simplerProblem: `Start with the concrete case: ${answer}`,
        requirements: [
            `Implement the ${topic} behavior described in the scenario without inventing application data.`,
            "Preserve accessible user feedback and distinguish success from failure.",
            "Verify the main case and the stated boundary case with repeatable checks."
        ],
        examples: [
            { input: problem, output: answer, explanation: `This expected result addresses the specific ${topic} scenario and its stated constraints.` },
            { input: edge, output: solution, explanation: "This second case checks the boundary condition rather than repeating the happy path." }
        ],
        tests: [
            { name: "Primary scenario", input: problem, expected: answer },
            { name: "Boundary scenario", input: edge, expected: solution }
        ],
        hints: [
            `Identify the user-visible failure mode in this ${topic} scenario before choosing an implementation.`,
            "Keep one source of truth, validate at system boundaries, and test the failure path as well as the normal path."
        ],
        learningObjectives: [
            `Apply ${topic} techniques to a realistic frontend engineering task.`,
            "Explain the trade-off, test the edge case, and communicate what the evidence does and does not prove."
        ],
        conceptsToReview: [topic, "React application architecture", "Frontend verification"],
        prerequisites: [],
        approach: `Translate the scenario into a small contract: identify the source of truth, observable result, and failure boundary. Implement only the behavior needed by the acceptance criteria, then test the primary example and the edge case.`,
        walkthrough: `For the primary case, ${answer} For the boundary case, ${edge} The supplied reference implementation illustrates one valid approach; adapt it to the project's actual API and runtime rather than copying assumptions that do not apply.`,
        solutionCode: solution,
        solutionLines: [answer, edge, solution],
        commonMistakes: [
            "Testing only the initial successful render and ignoring an empty, invalid, or late response.",
            "Adding abstraction or caching without evidence that it improves the stated user outcome."
        ],
        followUp,
        completionCriteria: [
            "The implementation meets the concrete behavior in the problem statement.",
            "Both supplied examples produce the expected result.",
            "The explanation identifies the relevant trade-off and a repeatable verification step."
        ],
        starterCode: `// ${topic}: implement the scenario described above\n// Keep the state/data boundary explicit and add the listed checks.\n`
    };
};

export const FRONTEND_ADVANCED_PRACTICE = Object.fromEntries(
    Object.entries(scenarios).map(([topic, exercises]) => [
        topic,
        exercises.map((exercise, index) => buildExercise(topic, exercise, index))
    ])
);
